-- =====================================================================
-- SABORES Y RUTAS DE SUCRE - MIGRACIÓN A POSTGRESQL
-- 01. ESQUEMA (tablas, restricciones e índices)
-- Origen: MySQL 8 / MariaDB 10.11   Destino: PostgreSQL 14+ (probado en PostgreSQL 18)
--
-- Antes de ejecutar: crear la base y conectarse a ella.
--   CREATE DATABASE sabores_rutas_sucre ENCODING 'UTF8';
--   (en pgAdmin: clic derecho en Databases > Create; luego Query Tool)
--
-- Adaptaciones principales (ver tabla completa en el informe, 8.2):
--   INT AUTO_INCREMENT      -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--   TINYINT(1) (activo)     -> BOOLEAN
--   TINYINT (estrellas)     -> SMALLINT
--   DATETIME                -> TIMESTAMP
--   DECIMAL(p,s)            -> NUMERIC(p,s)
--   ENGINE=InnoDB, CHARSET  -> se eliminan (PostgreSQL no usa motores)
--   INDEX dentro de CREATE  -> CREATE INDEX aparte
-- =====================================================================

DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;

-- ---------------------------------------------------------------------
-- Seguridad
-- ---------------------------------------------------------------------
CREATE TABLE roles (
  id_rol      INTEGER GENERATED BY DEFAULT AS IDENTITY,
  nombre_rol  VARCHAR(40)  NOT NULL,
  descripcion VARCHAR(255) NULL,
  CONSTRAINT pk_roles PRIMARY KEY (id_rol),
  CONSTRAINT uq_roles_nombre UNIQUE (nombre_rol)
);

CREATE TABLE usuarios (
  id_usuario     INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_rol         INTEGER      NOT NULL,
  nombre         VARCHAR(120) NOT NULL,
  email          VARCHAR(150) NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  activo         BOOLEAN      NOT NULL DEFAULT TRUE,
  fecha_creacion TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_usuarios PRIMARY KEY (id_usuario),
  CONSTRAINT uq_usuarios_email UNIQUE (email),
  CONSTRAINT fk_usuarios_roles FOREIGN KEY (id_rol) REFERENCES roles (id_rol)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- Catálogos
-- ---------------------------------------------------------------------
CREATE TABLE municipios (
  id_municipio INTEGER GENERATED BY DEFAULT AS IDENTITY,
  nombre       VARCHAR(80) NOT NULL,
  CONSTRAINT pk_municipios PRIMARY KEY (id_municipio),
  CONSTRAINT uq_municipios_nombre UNIQUE (nombre)
);

CREATE TABLE categorias (
  id_categoria INTEGER GENERATED BY DEFAULT AS IDENTITY,
  nombre       VARCHAR(60)  NOT NULL,
  descripcion  VARCHAR(255) NULL,
  CONSTRAINT pk_categorias PRIMARY KEY (id_categoria),
  CONSTRAINT uq_categorias_nombre UNIQUE (nombre)
);

CREATE TABLE tipos_recurso (
  id_tipo_recurso INTEGER GENERATED BY DEFAULT AS IDENTITY,
  nombre          VARCHAR(60) NOT NULL,
  CONSTRAINT pk_tipos_recurso PRIMARY KEY (id_tipo_recurso),
  CONSTRAINT uq_tipos_recurso_nombre UNIQUE (nombre)
);

-- ---------------------------------------------------------------------
-- Oferta turística
-- ---------------------------------------------------------------------
CREATE TABLE operadores (
  id_operador      INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_usuario       INTEGER      NULL,
  nombre_comercial VARCHAR(120) NOT NULL,
  nit              VARCHAR(20)  NOT NULL,
  telefono         VARCHAR(20)  NOT NULL,
  email            VARCHAR(150) NOT NULL,
  activo           BOOLEAN      NOT NULL DEFAULT TRUE,
  fecha_registro   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_operadores PRIMARY KEY (id_operador),
  CONSTRAINT uq_operadores_nit UNIQUE (nit),
  CONSTRAINT fk_operadores_usuarios FOREIGN KEY (id_usuario) REFERENCES usuarios (id_usuario)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE TABLE recursos (
  id_recurso      INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_tipo_recurso INTEGER      NOT NULL,
  id_municipio    INTEGER      NULL,
  nombre          VARCHAR(120) NOT NULL,
  descripcion     VARCHAR(255) NULL,
  telefono        VARCHAR(20)  NULL,
  activo          BOOLEAN      NOT NULL DEFAULT TRUE,
  CONSTRAINT pk_recursos PRIMARY KEY (id_recurso),
  CONSTRAINT fk_recursos_tipos FOREIGN KEY (id_tipo_recurso) REFERENCES tipos_recurso (id_tipo_recurso)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_recursos_municipios FOREIGN KEY (id_municipio) REFERENCES municipios (id_municipio)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE TABLE experiencias (
  id_experiencia            INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_operador               INTEGER       NOT NULL,
  id_categoria              INTEGER       NOT NULL,
  id_municipio              INTEGER       NOT NULL,
  titulo                    VARCHAR(150)  NOT NULL,
  descripcion               TEXT          NOT NULL,
  duracion_horas            NUMERIC(4,1)  NOT NULL,
  precio_base_cop           NUMERIC(12,2) NOT NULL,
  capacidad_max             INTEGER       NOT NULL,
  condiciones_participacion TEXT          NULL,
  estado_experiencia        VARCHAR(15)   NOT NULL DEFAULT 'ACTIVA',
  fecha_publicacion         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_experiencias PRIMARY KEY (id_experiencia),
  CONSTRAINT fk_experiencias_operadores FOREIGN KEY (id_operador) REFERENCES operadores (id_operador)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_experiencias_categorias FOREIGN KEY (id_categoria) REFERENCES categorias (id_categoria)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_experiencias_municipios FOREIGN KEY (id_municipio) REFERENCES municipios (id_municipio)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT ck_experiencias_duracion  CHECK (duracion_horas > 0),
  CONSTRAINT ck_experiencias_precio    CHECK (precio_base_cop >= 0),
  CONSTRAINT ck_experiencias_capacidad CHECK (capacidad_max > 0),
  CONSTRAINT ck_experiencias_estado    CHECK (estado_experiencia IN ('ACTIVA','INACTIVA','BORRADOR'))
);

CREATE TABLE experiencia_recurso (
  id_experiencia INTEGER NOT NULL,
  id_recurso     INTEGER NOT NULL,
  CONSTRAINT pk_experiencia_recurso PRIMARY KEY (id_experiencia, id_recurso),
  CONSTRAINT fk_exprec_experiencias FOREIGN KEY (id_experiencia) REFERENCES experiencias (id_experiencia)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_exprec_recursos FOREIGN KEY (id_recurso) REFERENCES recursos (id_recurso)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE TABLE programacion (
  id_programacion     INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_experiencia      INTEGER     NOT NULL,
  fecha_actividad     DATE        NOT NULL,
  hora_inicio         TIME        NOT NULL,
  cupos_totales       INTEGER     NOT NULL,
  cupos_disponibles   INTEGER     NOT NULL,
  estado_programacion VARCHAR(15) NOT NULL DEFAULT 'PROGRAMADA',
  CONSTRAINT pk_programacion PRIMARY KEY (id_programacion),
  CONSTRAINT fk_programacion_experiencias FOREIGN KEY (id_experiencia) REFERENCES experiencias (id_experiencia)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT ck_programacion_cupos        CHECK (cupos_disponibles >= 0 AND cupos_totales > 0),
  CONSTRAINT ck_programacion_cupos_limite CHECK (cupos_disponibles <= cupos_totales),
  CONSTRAINT ck_programacion_estado       CHECK (estado_programacion IN ('PROGRAMADA','CANCELADA','FINALIZADA'))
);

-- ---------------------------------------------------------------------
-- Demanda
-- ---------------------------------------------------------------------
CREATE TABLE visitantes (
  id_visitante   INTEGER GENERATED BY DEFAULT AS IDENTITY,
  nombre         VARCHAR(80)  NOT NULL,
  apellido       VARCHAR(80)  NOT NULL,
  email          VARCHAR(150) NOT NULL,
  telefono       VARCHAR(20)  NULL,
  fecha_registro TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_visitantes PRIMARY KEY (id_visitante),
  CONSTRAINT uq_visitantes_email UNIQUE (email)
);

CREATE TABLE reservas (
  id_reserva         INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_visitante       INTEGER       NOT NULL,
  id_programacion    INTEGER       NOT NULL,
  cantidad_personas  INTEGER       NOT NULL,
  monto_total_cop    NUMERIC(12,2) NOT NULL,
  estado_reserva     VARCHAR(10)   NOT NULL DEFAULT 'PENDIENTE',
  fecha_reserva      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  fecha_cancelacion  TIMESTAMP     NULL,
  CONSTRAINT pk_reservas PRIMARY KEY (id_reserva),
  CONSTRAINT fk_reservas_visitantes FOREIGN KEY (id_visitante) REFERENCES visitantes (id_visitante)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_reservas_programacion FOREIGN KEY (id_programacion) REFERENCES programacion (id_programacion)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT ck_reservas_personas CHECK (cantidad_personas > 0),
  CONSTRAINT ck_reservas_monto    CHECK (monto_total_cop >= 0),
  CONSTRAINT ck_reservas_estado   CHECK (estado_reserva IN ('PENDIENTE','CONFIRMADA','COMPLETADA','CANCELADA'))
);

CREATE TABLE pagos (
  id_pago                INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_reserva             INTEGER       NOT NULL,
  monto_cop              NUMERIC(12,2) NOT NULL,
  metodo_pago            VARCHAR(20)   NOT NULL,
  estado_pago            VARCHAR(12)   NOT NULL DEFAULT 'PENDIENTE',
  referencia_transaccion VARCHAR(64)   NULL,
  fecha_pago             TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_pagos PRIMARY KEY (id_pago),
  CONSTRAINT fk_pagos_reservas FOREIGN KEY (id_reserva) REFERENCES reservas (id_reserva)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT ck_pagos_monto  CHECK (monto_cop > 0),
  CONSTRAINT ck_pagos_estado CHECK (estado_pago IN ('PENDIENTE','APROBADO','RECHAZADO','REEMBOLSADO')),
  CONSTRAINT ck_pagos_metodo CHECK (metodo_pago IN ('EFECTIVO','TRANSFERENCIA','TARJETA','OTRO'))
);

CREATE TABLE valoraciones (
  id_valoracion        INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_reserva           INTEGER   NOT NULL,
  puntuacion_estrellas SMALLINT  NOT NULL,
  comentario           TEXT      NULL,
  fecha_valoracion     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_valoraciones PRIMARY KEY (id_valoracion),
  CONSTRAINT uq_valoraciones_reserva UNIQUE (id_reserva),
  CONSTRAINT fk_valoraciones_reservas FOREIGN KEY (id_reserva) REFERENCES reservas (id_reserva)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT ck_valoraciones_puntuacion CHECK (puntuacion_estrellas BETWEEN 1 AND 5)
);

CREATE TABLE auditoria_cancelaciones (
  id_auditoria      INTEGER GENERATED BY DEFAULT AS IDENTITY,
  id_reserva        INTEGER       NOT NULL,
  fecha_cancelacion TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  usuario_bd        VARCHAR(100)  NOT NULL,
  monto_perdido_cop NUMERIC(12,2) NOT NULL,
  motivo            VARCHAR(255)  NULL,
  CONSTRAINT pk_auditoria_cancelaciones PRIMARY KEY (id_auditoria),
  CONSTRAINT fk_auditoria_reservas FOREIGN KEY (id_reserva) REFERENCES reservas (id_reserva)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

-- ---------------------------------------------------------------------
-- Índices (en PostgreSQL se crean fuera del CREATE TABLE)
-- ---------------------------------------------------------------------
CREATE INDEX idx_reservas_prog_estado ON reservas USING btree (id_programacion, estado_reserva);
CREATE INDEX idx_reservas_fecha_estado ON reservas (fecha_reserva, estado_reserva);
CREATE INDEX idx_visitantes_nombre ON visitantes (apellido, nombre);
CREATE INDEX idx_experiencias_municipio_categoria ON experiencias (id_municipio, id_categoria);
CREATE INDEX idx_experiencias_estado ON experiencias (estado_experiencia);
CREATE INDEX idx_programacion_fecha_estado ON programacion (fecha_actividad, estado_programacion);
CREATE INDEX idx_pagos_estado_fecha ON pagos (estado_pago, fecha_pago);
-- MySQL crea automáticamente un índice por cada llave foránea; PostgreSQL
-- no, así que se agregan los de las FK más consultadas.
CREATE INDEX idx_experiencias_operador ON experiencias (id_operador);
CREATE INDEX idx_programacion_experiencia ON programacion (id_experiencia);
CREATE INDEX idx_reservas_visitante ON reservas (id_visitante);
CREATE INDEX idx_pagos_reserva ON pagos (id_reserva);

-- FIN 01
